class Solution { private final Map<String,Integer> counts=new HashMap<>();private final List<TreeNode> answer=new ArrayList<>();public List<TreeNode> findDuplicateSubtrees(TreeNode root){serialize(root);return answer;}private String serialize(TreeNode node){if(node==null)return "#";String key=node.val+","+serialize(node.left)+","+serialize(node.right);int count=counts.getOrDefault(key,0)+1;counts.put(key,count);if(count==2)answer.add(node);return key;} }
